from abc import ABC, abstractmethod


class Tea(ABC):
    @abstractmethod
    def get_cost(self):
        pass

    @abstractmethod
    def get_description(self):
        pass


class PlainTea(Tea):
    def get_cost(self):
        return 1.00

    def get_description(self):
        return "Plain Tea"


class TeaDecorator(Tea):
    def __init__(self, inner):
        self.inner = inner


class LemonDecorator(TeaDecorator):
    def __init__(self, inner):
        super().__init__(inner)

    def get_cost(self):
        return self.inner.get_cost() + 0.20

    def get_description(self):
        return f"{self.inner.get_description()}, Lemon"


class HoneyDecorator(TeaDecorator):
    def __init__(self, inner):
        super().__init__(inner)

    def get_cost(self):
        return self.inner.get_cost() + 0.30

    def get_description(self):
        return f"{self.inner.get_description()}, Honey"


class MintDecorator(TeaDecorator):
    def __init__(self, inner):
        super().__init__(inner)

    def get_cost(self):
        return self.inner.get_cost() + 0.25

    def get_description(self):
        return f"{self.inner.get_description()}, Mint"


if __name__ == "__main__":
    order1 = PlainTea()
    print(f"Order 1: {order1.get_description()} | ${order1.get_cost():.2f}")

    order2 = HoneyDecorator(LemonDecorator(PlainTea()))
    print(f"Order 2: {order2.get_description()} | ${order2.get_cost():.2f}")

    order3 = MintDecorator(HoneyDecorator(HoneyDecorator(PlainTea())))
    print(f"Order 3: {order3.get_description()} | ${order3.get_cost():.2f}")

