#include <bits/stdc++.h>
using namespace std;

class Tea {
public:
    virtual double getCost() = 0;
    virtual string getDescription() = 0;
    virtual ~Tea() = default;
};

class PlainTea : public Tea {
public:
    double getCost() override { return 1.00; }
    string getDescription() override { return "Plain Tea"; }
};

class TeaDecorator : public Tea {
protected:
    Tea* inner;
public:
    TeaDecorator(Tea* inner) : inner(inner) {}
};

class LemonDecorator : public TeaDecorator {
public:
    LemonDecorator(Tea* inner) : TeaDecorator(inner) {}

    double getCost() override { return inner->getCost() + 0.20; }
    string getDescription() override { return inner->getDescription() + ", Lemon"; }
};

class HoneyDecorator : public TeaDecorator {
public:
    HoneyDecorator(Tea* inner) : TeaDecorator(inner) {}

    double getCost() override { return inner->getCost() + 0.30; }
    string getDescription() override { return inner->getDescription() + ", Honey"; }
};

class MintDecorator : public TeaDecorator {
public:
    MintDecorator(Tea* inner) : TeaDecorator(inner) {}

    double getCost() override { return inner->getCost() + 0.25; }
    string getDescription() override { return inner->getDescription() + ", Mint"; }
};

int main() {
    cout << fixed << setprecision(2);

    PlainTea plain1;
    Tea* order1 = &plain1;
    cout << "Order 1: " << order1->getDescription() << " | $" << order1->getCost() << endl;

    PlainTea plain2;
    LemonDecorator lemon2(&plain2);
    HoneyDecorator order2(&lemon2);
    cout << "Order 2: " << order2.getDescription() << " | $" << order2.getCost() << endl;

    PlainTea plain3;
    HoneyDecorator honey3a(&plain3);
    HoneyDecorator honey3b(&honey3a);
    MintDecorator order3(&honey3b);
    cout << "Order 3: " << order3.getDescription() << " | $" << order3.getCost() << endl;

    return 0;
}
